    qo_output.usable = (uint32_t)0U;
    qo_output.total_weight = 0.0;
    qo_output.mean_alignment = 0.0;
    qo_output.body_separation_sine = 0.0;
    qo_output.reference_separation_sine = 0.0;
    qo_output.weighted_body = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (total_weight > 0.0) {
    mean_alignment = alignment_sum / total_weight;
    qo_output.weighted_body = adcs_vec3_scale(&wsum, 1.0 / total_weight);
}

body_cross = adcs_vec3_cross(&body_unit[0], &body_unit[1]);
ref_cross = adcs_vec3_cross(&ref_unit[0], &ref_unit[1]);
body_sin = adcs_vec3_norm(&body_cross);
ref_sin = adcs_vec3_norm(&ref_cross);

ready_geometry = ((total_weight >= qo_config.minimum_weight) &&
                  (body_sin >= qo_config.minimum_separation_sine) &&
                  (ref_sin >= qo_config.minimum_separation_sine)) ? 1 : 0;

qo_output.total_weight = total_weight;
qo_output.mean_alignment = mean_alignment;
qo_output.body_separation_sine = body_sin;
qo_output.reference_separation_sine = ref_sin;
qo_output.usable = ready_geometry ? (uint32_t)qo_input.count : (uint32_t)0U;

if (!enabled) {
    qo_state.mode = QO_WAIT;
    qo_state.good = 0U;
    qo_state.bad_streak = 0U;
    qo_output.mode = QO_WAIT;
    qo_output.good = 0U;
    qo_output.usable = (uint32_t)0U;
    return;
}

if (ready_geometry) {
    qo_state.good += 1U;
    qo_state.bad_streak = 0U;
    qo_state.mode = (qo_state.good >= qo_config.required_good) ? QO_SOLVE : QO_WAIT;
    qo_output.mode = qo_state.mode;
    qo_output.good = qo_state.good;
} else {
    qo_state.bad_streak += 1U;
    if (qo_state.bad_streak > qo_config.max_consecutive_bad) {
        qo_state.good = 0U;
        qo_state.bad_streak = 0U;
        qo_state.mode = QO_WAIT;
        qo_output.mode = QO_WAIT;
        qo_output.good = 0U;
        qo_output.usable = (uint32_t)0U;
    } else {
        qo_state.mode = QO_HOLD;
        qo_output.mode = QO_HOLD;
        qo_output.good = qo_state.good;
        qo_output.usable = 0U;
    }
}
